-- Synthetic fixtures. Loaded ONLY in a labelled, disposable local container.
DROP SCHEMA public CASCADE;
CREATE SCHEMA public;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role BYPASSRLS; END IF;
END $$;
CREATE TYPE public.estado_resultado AS ENUM ('pendiente','aprobado','reprobado');
CREATE TYPE public.tipo_certificado AS ENUM ('aprobacion','participacion');
CREATE TYPE public.estado_certificado AS ENUM ('valido','anulado');
CREATE TABLE public.usuarios(id BIGINT PRIMARY KEY,nombre_completo TEXT,rol TEXT NOT NULL,activo BOOLEAN DEFAULT true);
CREATE TABLE public.cursos(id BIGINT PRIMARY KEY,nombre TEXT NOT NULL,codigo TEXT,horas INTEGER,duracion_horas INTEGER,
  nota_minima NUMERIC DEFAULT 70,asistencia_minima NUMERIC DEFAULT 80,fecha_fin DATE);
CREATE TABLE public.inscripciones(id INTEGER PRIMARY KEY,curso_id BIGINT REFERENCES cursos,participante_id BIGINT REFERENCES usuarios,estado TEXT);
CREATE TABLE public.sesiones(id BIGINT PRIMARY KEY,curso_id BIGINT REFERENCES cursos,fecha DATE);
CREATE TABLE public.asistencias_participantes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sesion_id BIGINT REFERENCES sesiones,inscripcion_id BIGINT,estado TEXT,UNIQUE(sesion_id,inscripcion_id));
CREATE TABLE public.evaluaciones(id BIGINT PRIMARY KEY,curso_id BIGINT REFERENCES cursos,nombre TEXT,ponderacion NUMERIC);
CREATE TABLE public.calificaciones(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,evaluacion_id BIGINT REFERENCES evaluaciones,
  inscripcion_id BIGINT,nota NUMERIC,UNIQUE(evaluacion_id,inscripcion_id));
CREATE TABLE public.resultados_curso(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,inscripcion_id BIGINT UNIQUE NOT NULL,
  nota_final NUMERIC NOT NULL CHECK(nota_final BETWEEN 0 AND 100),porcentaje_asistencia NUMERIC NOT NULL CHECK(porcentaje_asistencia BETWEEN 0 AND 100),
  cumple_nota BOOLEAN NOT NULL DEFAULT false,cumple_asistencia BOOLEAN NOT NULL DEFAULT false,
  estado estado_resultado NOT NULL DEFAULT 'pendiente',fecha_resultado TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.certificados(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  resultado_curso_id BIGINT UNIQUE NOT NULL REFERENCES resultados_curso ON DELETE CASCADE,
  codigo_verificacion VARCHAR(50) NOT NULL CONSTRAINT certificados_codigo_verificacion_key UNIQUE,
  tipo tipo_certificado NOT NULL DEFAULT 'aprobacion',fecha_emision TIMESTAMPTZ NOT NULL DEFAULT now(),url_pdf VARCHAR(500),
  url_verificacion VARCHAR(500) UNIQUE NOT NULL,codigo_qr VARCHAR(500),emitido_fisico BOOLEAN DEFAULT false,
  emitido_digital BOOLEAN DEFAULT true,estado estado_certificado NOT NULL DEFAULT 'valido');
CREATE TABLE public.anulaciones_certificados(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  certificado_id BIGINT UNIQUE REFERENCES certificados,anulado_por BIGINT REFERENCES usuarios,motivo VARCHAR(500),fecha_anulacion TIMESTAMPTZ DEFAULT now());
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;

INSERT INTO usuarios VALUES (1,'Administración de prueba','administrador',true),(2,'Ana Álvarez','participante',true),
  (3,'Otra participante','participante',true),(4,'Instructor de prueba','instructor',true);
